import{_ as c,D as a,o as t,c as r,m as o,a as i,G as n,S as F}from"./chunks/framework.DuIEtbrD.js";const C=JSON.parse('{"title":"如何使用Chrome Performance优化性能问题","description":"通常前端开发者面对最大的性能问题就是页面的加载以及事件影响问题,本文通过使用Chrome Performance来优化性能问题","frontmatter":{"title":"如何使用Chrome Performance优化性能问题","description":"通常前端开发者面对最大的性能问题就是页面的加载以及事件影响问题,本文通过使用Chrome Performance来优化性能问题","keywords":"Performance,ChromeDevTools,DCL,FP,LCP,内存优化,heap,CPU,性能优化","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-browser.png"},"headers":[],"relativePath":"article/2022/chrome-performance.md","filePath":"article/2022/chrome-performance.md","lastUpdated":1776945570000}'),D={name:"article/2022/chrome-performance.md"};function y(d,s,m,h,u,b){const l=a("Obsolete"),e=a("Reward"),p=a("Gitalk");return t(),r("div",null,[s[0]||(s[0]=o("h1",{id:"如何使用chrome-performance优化性能问题",tabindex:"-1"},[i("如何使用Chrome Performance优化性能问题 "),o("a",{class:"header-anchor",href:"#如何使用chrome-performance优化性能问题","aria-label":'Permalink to "如何使用Chrome Performance优化性能问题"'},"​")],-1)),n(l,{date:"2022-03-01"}),s[1]||(s[1]=F(`<p>本次来分享下ChromeDevTools Performance面板的使用技巧，对于前端开发者来说页面的性能表现在运行指标中占比是很高的。面对复杂的项目业务难免会有在代码层面造成的性能问题，对于浏览器端开发者来说掌握Performance相关技巧还是非常重要的</p><div class="warning custom-block"><p class="custom-block-title">小贴士</p><p>文章中涉及到的示例代码你都可以从 <a href="https://github.com/ihengshuai/blog-case/tree/gh-pages/chrome/performance" target="_blank" rel="noreferrer">这里查看</a> ，若对你有用还望点赞支持</p></div><h2 id="打开面板" tabindex="-1">打开面板 <a class="header-anchor" href="#打开面板" aria-label="Permalink to &quot;打开面板&quot;">​</a></h2><p>首先要打开Performance面板我们才可以进行相关操作，默认情况下打开开发者工具后，在顶部的tabs中就会看到有个Performance选项，直接点击就可以，或者点击最后面的更多按钮查看更多</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_14.39.56.png" alt=""></p><p>如果没有可以打开面板然后输入<code>Command+Shift+P</code>调出命令面板后，再输入<code>Performance</code>看到对应的条例后点击它就可以打开了</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_14.38.30.png" alt=""></p><p>这是一份完整的面板结果示例</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_14.52.48%20.png" alt=""></p><p>Performance面板由 <code>控制面板</code>、<code>概览面板</code>、<code>火焰图</code> 和 <code>详情面板</code> 几部分组成</p><h2 id="控制面板" tabindex="-1">控制面板 <a class="header-anchor" href="#控制面板" aria-label="Permalink to &quot;控制面板&quot;">​</a></h2><p>控制面板位于顶部，主要用于管理性能分析的录制过程和配置选项。以下是控制面板的主要功能介绍：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_14.56.04.png" alt=""></p><ul><li><code>Record 按钮</code>：开始或停止性能数据的录制，结束后会生成一份详细的性能分析报告</li><li><code>Reload 按钮</code>：在录制期间重新加载页面，通常用于分析页面加载过程的性能表现（如首次绘制、资源加载）</li><li><code>Clear 按钮</code>：清除当前录制的数据</li><li><code>ScreenShots</code>：用于控制记录期间是否记录屏幕截图，一般用它来观察动画的具体过程是否流程等等</li><li><code>Memory</code>：用于控制记录期间是否开启内存大小变化，开启后就可以查看内存的使用情况了</li></ul><p>除此之外你还可以点击最后面的设置按钮查看更多的功能选项：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_14.56.24.png" alt=""></p><p>比如：控制CPU的执行效率、网络的网速、样式统计等等，这些功能给开发者模拟不同的环境提供了很多便利</p><h2 id="开始记录" tabindex="-1">开始记录 <a class="header-anchor" href="#开始记录" aria-label="Permalink to &quot;开始记录&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_14.58.33.png" alt=""></p><p>开始一份性能记录可以通过 <code>重载页面开始记录</code> 或 <code>运行时记录</code>，二者的区别在于前者可以记录页面的加载过程，而运行时记录则就是从当前页面的状态开始记录，根据用户的操作等等产生一份报告</p><p>读者可以根据实际情况选择记录</p><h2 id="概览面板" tabindex="-1">概览面板 <a class="header-anchor" href="#概览面板" aria-label="Permalink to &quot;概览面板&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_15.03.13.png" alt=""></p><p>概览面板用于展示性能数据的整体概览，开发者可以通过概览面板快速识别性能瓶颈和页面的关键问题点。概览面板也是横轴为时间轴，纵轴是不同维度的记录情况。在上图可以看到：</p><ul><li><code>CPU</code>：有颜色的区域标识CPU在工作</li><li><code>Net</code>：网络活动图展示页面的网络请求活动，包括资源的加载时间和数据量。蓝色代表资源加载， 黄色代表请求延迟</li><li>截图：截图可以看到每一帧的网页展示情况</li><li><code>Heap</code>：内存活动图记录内存随时间的推移使用情况</li></ul><p>通过鼠标滚轮可以放大或缩小时间轴，方便开发者可以更专注于某一个时间点的排查</p><h2 id="火焰图" tabindex="-1">火焰图 <a class="header-anchor" href="#火焰图" aria-label="Permalink to &quot;火焰图&quot;">​</a></h2><p>火焰图（Flame Chart）是 Chrome DevTools Performance 面板中的一个核心部分，用于展示和分析页面性能数据的详细信息。它以火焰状的层次结构显示各个任务的执行顺序和耗时，帮助开发者深入了解页面的主线程和其他线程的性能瓶颈</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_15.04.08.png" alt=""></p><p>火焰图的顶部是时间轴，单位为毫秒（ms），表示录制过程中各个任务发生的时间点。时间轴从左到右依次递增，反映任务的执行顺序</p><p>火焰图的纵轴是以不同维度来记录的性能情况，如：<code>Network</code>、<code>Frame</code>、<code>Main主线程</code>、<code>GPU</code>、<code>其他线程</code>等等</p><p>通常情况下的<u>性能问题我们都是会从主线程开始，他记录了页面的加载解析、绘制、js的执行</u>等等情况，而这些通常都是和开发者息息相关的问题</p><h3 id="任务" tabindex="-1">任务 <a class="header-anchor" href="#任务" aria-label="Permalink to &quot;任务&quot;">​</a></h3><p>分析主线程首先要知道它的执行机制是怎么回事❓</p><p>主线程以任务为基本单位不断执行，这些任务覆盖很广，包括：页面解析、渲染、JS执行、事件等等。主线程每次只能运行一个任务，所有的任务按循序执行，下图是一个主线程的任务执行图：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.10.04.png" alt=""></p><p>每个任务包含一系列的调用过程，通常被称为调用栈</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.19.13.png" alt=""></p><p>不同的任务会被标记为不同的颜色，<code>黄色js执行任务</code>、<code>紫色样式计算布局等</code>、<code>绿色渲染任务如绘制和合成</code>、<code>蓝色网络请求</code></p><h3 id="优化长任务" tabindex="-1">优化长任务 <a class="header-anchor" href="#优化长任务" aria-label="Permalink to &quot;优化长任务&quot;">​</a></h3><p>当任务的执行时间超过 50-60ms 就会被认为是长任务，长任务被看作是阻碍性能的头号大敌。火焰图上也会通过<code>右上角的红色标识</code>这是长任务，通过这个可以快速的看到那些任务有性能问题</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.26.46.png" alt=""></p><p>初次之外一些会造成页面卡顿、帧率问题的任务通常会被显示为红色</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.51.07.png" alt=""></p><p>当知道了哪些任务出现问题时，就可以聚焦这里开始分析了。通常火焰图需要结合详情信息区域进行排查具体的代码问题</p><h2 id="详细信息" tabindex="-1">详细信息 <a class="header-anchor" href="#详细信息" aria-label="Permalink to &quot;详细信息&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_15.04.53.png" alt=""></p><p>详细信息区域位于性能分析的底部，它用于显示当前选中任务的详细性能数据和相关信息，帮助开发者深入理解性能瓶颈的具体原因</p><p>详细信息由<code>Summary（概要）</code>、<code>Bottom-Up（自下而上分析）</code>、<code>Call Tree（调用栈）</code>、<code>Event Log（事件日志）</code>几部分组成</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>提供选中任务的简要信息，将<code>当前选中任务</code>的所有任务类型执行情况以饼图形式展示出来</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.33.25.png" alt=""></p><p>上面包含了加载时间、脚本执行时间、页面渲染时间、绘制时间、Idle空闲时间等等，通过饼图面板可以快速的看到什么类型的任务最耗时</p><h3 id="bottom-up" tabindex="-1">Bottom-Up <a class="header-anchor" href="#bottom-up" aria-label="Permalink to &quot;Bottom-Up&quot;">​</a></h3><p>按照任务的耗时进行聚合，展示各个任务的调用情况以及记录执行的耗时情况，读者可以点击不同的聚合直到底层执行</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.39.18.png" alt=""></p><p>每个聚合包含当前函数调用时间以及子调用的执行时间</p><p>这里也可以看出哪些函数任务执行很耗时</p><h3 id="call-tree" tabindex="-1">Call Tree <a class="header-anchor" href="#call-tree" aria-label="Permalink to &quot;Call Tree&quot;">​</a></h3><p>显示选中任务的调用堆栈，包含函数调用链的每一层、文件名、行号和列号，顶层为当前任务，底层为最初的调用者。通过调用栈可以很方便的看到一些长任务很耗时的脚本执行问题所在</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.42.55.png" alt=""></p><p>找对应的长任务后点击后方的文件名就可以跳转到源码位置(页面加载的文件)</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.44.30.png" alt=""></p><p>Chrome会在源码左侧位置标注当前代码的执行时间</p><h3 id="eventlog" tabindex="-1">EventLog <a class="header-anchor" href="#eventlog" aria-label="Permalink to &quot;EventLog&quot;">​</a></h3><p>列出选中时间范围内发生的所有事件，包括事件的名称、时间戳和持续时间</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.48.35.png" alt=""></p><p>通过此种方式可以快速看到有哪些事件非常耗时</p><h2 id="实时帧率" tabindex="-1">实时帧率 <a class="header-anchor" href="#实时帧率" aria-label="Permalink to &quot;实时帧率&quot;">​</a></h2><p>除了通过Performance记录性能外还有很多功能可以使用，如实时帧率用来实时监测页面的指标。开发者通过在命令面板输入：<code>fps</code>点击第一项就可以了</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.54.48.png" alt=""></p><p>打开后页面上会多一个实时面板，包含帧率、GPU、内存等指标</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-14_15.06.20.png" alt=""></p><h2 id="实时性能监控" tabindex="-1">实时性能监控 <a class="header-anchor" href="#实时性能监控" aria-label="Permalink to &quot;实时性能监控&quot;">​</a></h2><p>开发者通过在命令面板输入：<code>performance</code>然后选择monitor</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_10.56.40.png" alt=""></p><p>打开后会有一个监控窗口出现</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/perf-monitor.gif" alt=""></p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><p>Chrome DevTools还有很多强大的功能，如：断点、内存分析、Lighthouse、Layer等等，这些你都可以在命令面板中找到 <code>Command+Shif+P</code>，记得尝试一下</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_11.03.06.png" alt=""></p><h2 id="实战案例" tabindex="-1">实战案例 <a class="header-anchor" href="#实战案例" aria-label="Permalink to &quot;实战案例&quot;">​</a></h2><p>这里我们通过一个项目来演练下如何优化性能，项目源码</p><p>页面代码：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">&lt;!</span><span style="color:#F07178;">DOCTYPE</span><span style="color:#C792EA;"> html</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">html</span><span style="color:#C792EA;"> lang</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">en</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">head</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">link</span><span style="color:#C792EA;"> rel</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">stylesheet</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> href</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">./style.css</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">script</span><span style="color:#C792EA;"> src</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">./long-task.js</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;&lt;/</span><span style="color:#F07178;">script</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">head</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">body</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">div</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">box</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">script</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#C792EA;">    const</span><span style="color:#BABED8;"> box </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> document</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">querySelector</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">.box</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">    box</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">addEventListener</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">click</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;">  doWhile)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#C792EA;">    async</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> doWhile</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;"> {</span><span style="color:#89DDFF;font-style:italic;"> for</span><span style="color:#F07178;"> (</span><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;"> =</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#F78C6C;"> 10e8</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;">++</span><span style="color:#F07178;">) </span><span style="color:#89DDFF;">{}}</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;/</span><span style="color:#F07178;">script</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">body</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">html</span><span style="color:#89DDFF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p><code>long-task.js</code>源码：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">for</span><span style="color:#BABED8;"> (</span><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> i </span><span style="color:#89DDFF;">=</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i </span><span style="color:#89DDFF;">&lt;</span><span style="color:#F78C6C;"> 10e7</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;">++</span><span style="color:#BABED8;">) </span><span style="color:#89DDFF;">{}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后通过Chrome打开页面，开始Performance记录加载性能</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/2025-01-15%2011.10.26.gif" alt=""></p><p>通过性能结果报告可以一眼看出来哪里有性能瓶颈问题，我们通过红区就可以一眼看出</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_11.12.04.png" alt=""></p><h3 id="优化长任务-1" tabindex="-1">优化长任务 <a class="header-anchor" href="#优化长任务-1" aria-label="Permalink to &quot;优化长任务&quot;">​</a></h3><p>选中这里的任务查看详情面板</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_11.16.33.png" alt=""></p><p>发现这里的<code>doWhile</code>函数执行太耗时了，我们点击到对应的源码位置</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_11.18.08.png" alt=""></p><p>这里的业务逻辑紧紧是演示，那如果真实的情况也会发生这种执行耗时的任务呢？我们该怎么办❓</p><p>大家知道JS的EventLoop机制，而主线程上的任务就是EventLoop不断执行的过程，如果任务太耗时就会造成页面卡顿。那么通过EventLoop我们可以将 <u>长任务拆分为多个小任务通过EventLoop不断执行</u>，这样就不会造成卡顿了</p><p>我们改造下代码：通过<code>Promise</code>将任务不断推到下一个eventloop</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> doWhile</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  for</span><span style="color:#F07178;"> (</span><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;"> =</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#F78C6C;"> 10e8</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;">++</span><span style="color:#F07178;">) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#BABED8;">    console</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">log</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">click...</span><span style="color:#89DDFF;">&quot;</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line highlighted"><span style="color:#89DDFF;font-style:italic;">    await</span><span style="color:#89DDFF;"> new</span><span style="color:#FFCB6B;"> Promise</span><span style="color:#F07178;">(</span><span style="color:#BABED8;font-style:italic;">resolve</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#82AAFF;">      setTimeout</span><span style="color:#F07178;">(</span><span style="color:#BABED8;">resolve</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;"> 0</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">    }</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>再来看看效果：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/2025-01-15%2011.26.36.gif" alt=""></p><p>效果前后差异太大了，根本看不到一点卡顿‼️</p><p>除了Promise外，还可以通过主动使用调度器来避免卡顿问题，这里读者要知道卡顿是因为这段js任务一直占据着主线程，导致后续任务无法及时影响！那么开发者在写这种耗时任务时通过调度器将主线程让出，及时响应其他任务就会有卡顿了</p><div class="warning custom-block"><p class="custom-block-title">小贴士</p><p>scheduler API比较新部分浏览器还不支持，因此读者可以选择polyfill或者注意使用浏览器的版本</p></div><p>这里使用 <a href="https://developer.mozilla.org/en-US/docs/Web/API/Scheduler" target="_blank" rel="noreferrer">scheduler API</a> 进行调度：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> doWhile</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  for</span><span style="color:#F07178;"> (</span><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;"> =</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#F78C6C;"> 10e8</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;">++</span><span style="color:#F07178;">) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#BABED8;">    console</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">log</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">click...</span><span style="color:#89DDFF;">&quot;</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line highlighted"><span style="color:#89DDFF;font-style:italic;">    await</span><span style="color:#BABED8;"> scheduler</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">yield</span><span style="color:#F07178;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>来看看效果：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/2025-01-15%2011.32.36.gif" alt=""></p><p>会发现使用了调度器后还是会有一点点卡顿，但是不是很明显的卡顿，这里有个调度器的使用说明</p><blockquote><p><code>scheduler.yield()</code> 快速且高效，但会产生一些额外开销。如果 jobQueue 中的某些作业非常短，那么开销可能会迅速累积，导致用于让出和恢复的时间比执行实际工作的时间还多</p></blockquote><h3 id="优化资源加载" tabindex="-1">优化资源加载 <a class="header-anchor" href="#优化资源加载" aria-label="Permalink to &quot;优化资源加载&quot;">​</a></h3><p>在解决了点击事件的问题后，我们用鼠标放大火焰图拉到最前面，就会看到这里也有一个很耗时的任务</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_11.45.59.png" alt=""></p><p>根据任务的执行栈可以看出在解析HTML的过程中去执行了JS脚本导致任务过长，页面中确实有一个加载js脚本资源的代码。从图中最后面可以看到有一个蓝色线旁边写着 <code>DCL</code> 即Document Content Load也就是页面资源加载完毕，然后就会触发<code>DomContentLoad</code>事件，而这段js在这事件之前就执行了，这会严重影响页面指标</p><p>一般对于非首页很重的资源采取异步加载，然后根据执行时机选择<code>defer</code>和<code>async</code>，这里我们选择<code>defer</code></p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">script</span><span style="color:#C792EA;"> defer</span><span style="color:#C792EA;"> src</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">./long-task.js</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;&lt;/</span><span style="color:#F07178;">script</span><span style="color:#89DDFF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>再次查看执行情况：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_11.55.02.png" alt=""></p><p>发现当前脚本任务已经没有阻塞HTML解析了，而且任务的执行会超过<code>DCL</code>，会爆红根本原因在于太耗时。所以在项目中要对不是很重要的js资源做异步加载</p><h3 id="优化重绘-回流" tabindex="-1">优化重绘/回流 <a class="header-anchor" href="#优化重绘-回流" aria-label="Permalink to &quot;优化重绘/回流&quot;">​</a></h3><p>现在我们通过鼠标滚轮将视角拉到全局，会发现密密麻麻的一片紫色，占据了整个时间轴，紫色代表着页面布局渲染。由于页面上的<code>box</code>盒子一直在没有优化的情况下不断运动，所以会造成页面渲染</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_12.08.44.png" alt=""></p><p>我们随便选一个任务，然后从详情记录面板查看具体情况，发现会执行：<code>布局</code>、<code>样式计算</code>、<code>重绘</code>、<code>分层</code>等多个步骤</p><p>来看下我们的动画代码：</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">box</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  width</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 100px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  height</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 100px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  background-color</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  margin</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 10px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  animation</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1s</span><span style="color:#BABED8;"> linear infinite alternate box-animation</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@keyframes</span><span style="color:#BABED8;font-style:italic;"> box-animation</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#FFCB6B;">  from</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> margin-left</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#FFCB6B;">  to</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> margin-left</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 200px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>动画代码通过改变<code>margin</code>的形式改变位置，由于改变了元素的几何，因此会造成页面的重绘，这种动画是非常消耗性能的</p><p>现在我们优化下动画：</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">box</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">optimized</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  will-change</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> transform</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  animation-name</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> box-animation-optimized</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@keyframes</span><span style="color:#BABED8;font-style:italic;"> box-animation-optimized</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#FFCB6B;">  from</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> transform</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> translateX</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">);</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#FFCB6B;">  to</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> transform</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> translateX</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">200px</span><span style="color:#89DDFF;">);</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>上面我们使用<code>will-change</code>告诉浏览器这个元素要<code>分层处理</code>，然后动画改成<code>transform</code>合成动画，合成动画只会在<code>合成线程</code>上执行，而不会触发主线程进行重新渲染页面，大大提高效率</p><p>关于这些优化如果你不是很清楚的话，推荐阅读往期文章 <a href="/frontend/browser/base.html">「现代浏览器架构」</a></p><p>再来看看优化后的效果：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-01-15_12.05.10.png" alt=""></p><p>前后对比太明显了，后续的任务根本没有显示任何执行任务，因为它根本<code>没在主线程上运行</code></p><p>到这里的实战就告一段落了，还有很多实用的技能，敬请关注我后续文章</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>通过本文让读者可以了解到主线程是以任务为基本单位执行的，合理管理每个任务的执行时长以及样式动画，对提高页面运行效率有重要作用。这里简单归纳下：</p><ul><li>避免阻塞主线程</li><li>拆分长任务</li><li>禁止强制布局</li><li>先赋值再布局</li></ul>`,138)),n(e),n(p)])}const f=c(D,[["render",y]]);export{C as __pageData,f as default};
